package dev.veltraph.client.movement.device;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class DeviceInvocationIdentityTest {
 private final Object oldSession=new Object(),newSession=new Object(),packet=new Object(),transport=new Object();
 @Test void exactNormalNativeInvocationReturnsCapturedSession(){var call=DeviceInvocationIdentity.head(oldSession,packet,transport,true);assertEquals(DeviceInvocationIdentity.Result.RETURNED,DeviceInvocationIdentity.finish(call,oldSession,packet,transport,true));}
 @Test void oldSendReturnCannotCorrelateReplacementSession(){var call=DeviceInvocationIdentity.head(oldSession,packet,transport,true);assertEquals(DeviceInvocationIdentity.Result.INERT,DeviceInvocationIdentity.finish(call,newSession,packet,transport,true));}
 @Test void oldSendThrowCannotRevokeReplacementSession(){var call=DeviceInvocationIdentity.head(oldSession,packet,transport,true);assertEquals(DeviceInvocationIdentity.Result.INERT,DeviceInvocationIdentity.finish(call,newSession,packet,transport,false));}
 @Test void oldApplyReturnCannotBorrowNewSession(){var receive=DeviceInvocationIdentity.head(oldSession,packet,transport,true);assertEquals(DeviceInvocationIdentity.Result.INERT,DeviceInvocationIdentity.finish(receive,newSession,packet,transport,true));}
 @Test void noSessionAtReceiveHeadCannotBorrowNewSession(){var call=DeviceInvocationIdentity.head(null,packet,transport,false);assertNull(call);assertEquals(DeviceInvocationIdentity.Result.INERT,DeviceInvocationIdentity.finish(call,newSession,packet,transport,true));}
 @Test void receiveHeadBeforeSubmissionStaysRefusedEvenIfSubmissionLaterCompletes(){var call=DeviceInvocationIdentity.head(oldSession,packet,transport,false);assertEquals(DeviceInvocationIdentity.Result.REFUSED,DeviceInvocationIdentity.finish(call,oldSession,packet,transport,true));}
 @Test void originalThrowTargetsOnlyCapturedCurrentSession(){var call=DeviceInvocationIdentity.head(oldSession,packet,transport,true);assertEquals(DeviceInvocationIdentity.Result.THREW,DeviceInvocationIdentity.finish(call,oldSession,packet,transport,false));}
 @Test void foreignPacketObjectCannotBeSubstitutedAtReturn(){var call=DeviceInvocationIdentity.head(oldSession,packet,transport,true);assertEquals(DeviceInvocationIdentity.Result.INERT,DeviceInvocationIdentity.finish(call,oldSession,new Object(),transport,true));}
 @Test void foreignTransportCannotBeSubstitutedAtReturn(){var call=DeviceInvocationIdentity.head(oldSession,packet,transport,true);assertEquals(DeviceInvocationIdentity.Result.INERT,DeviceInvocationIdentity.finish(call,oldSession,packet,new Object(),true));}
 @Test void invocationCannotCompleteTwice(){var call=DeviceInvocationIdentity.head(oldSession,packet,transport,true);assertEquals(DeviceInvocationIdentity.Result.RETURNED,DeviceInvocationIdentity.finish(call,oldSession,packet,transport,true));assertEquals(DeviceInvocationIdentity.Result.INERT,DeviceInvocationIdentity.finish(call,oldSession,packet,transport,true));}
 @Test void nestedNewInvocationIndependentOfOldReturn(){var outer=DeviceInvocationIdentity.head(oldSession,packet,transport,true);var nestedPacket=new Object();var inner=DeviceInvocationIdentity.head(newSession,nestedPacket,transport,true);assertEquals(DeviceInvocationIdentity.Result.RETURNED,DeviceInvocationIdentity.finish(inner,newSession,nestedPacket,transport,true));assertEquals(DeviceInvocationIdentity.Result.INERT,DeviceInvocationIdentity.finish(outer,newSession,packet,transport,true));}
 @Test void nestedSameSessionInvocationsHaveSeparateCompletionTokens(){var outer=DeviceInvocationIdentity.head(oldSession,packet,transport,true);var inner=DeviceInvocationIdentity.head(oldSession,packet,transport,true);assertEquals(DeviceInvocationIdentity.Result.RETURNED,DeviceInvocationIdentity.finish(inner,oldSession,packet,transport,true));assertEquals(DeviceInvocationIdentity.Result.RETURNED,DeviceInvocationIdentity.finish(outer,oldSession,packet,transport,true));}
 @Test void retiredSessionCannotReceiveObserverFailure(){var call=DeviceInvocationIdentity.head(oldSession,packet,transport,true);assertFalse(DeviceInvocationIdentity.capturedCurrent(call,newSession));assertTrue(DeviceInvocationIdentity.capturedCurrent(call,oldSession));}
}
